// Leaf Map modeled by the ordered key list a construction path produces.
function leafMap(o) {
  return Object.keys(o).join('>');
}
function distinctLeaves(builder, n) {
  const seen = new Set();
  for (let i = 0; i < n; i++) seen.add(leafMap(builder(i)));
  return seen.size;
}

// STABLE: a, then b, then c -> one transition path -> one leaf Map.
function stable(i) {
  const o = {};
  o.a = i; o.b = i + 1; o.c = i + 2;
  return o;
}

// CHURNY: rotate which key is assigned first by index (3 orders),
// plus a late field on every other object (x2) -> 3 * 2 = 6 distinct branches.
function churny(i) {
  const o = {};
  const keys = ['a', 'b', 'c'];
  for (let k = 0; k < 3; k++) {
    const key = keys[(i + k) % 3];
    o[key] = 1;
  }
  if (i % 2 === 0) o.late = i; // late conditional field branches the tree further
  return o;
}

const stableLeaves = distinctLeaves(stable, 6);
const churnyLeaves = distinctLeaves(churny, 6);
console.log('stable=' + stableLeaves + ' churny=' + churnyLeaves);

