const CANON = ['id', 'name', 'amount'];

function build(input) {
  const out = {};
  // intended: assign in canonical order; bug: iterates the INPUT's own order
  for (const k of Object.keys(input)) {
    out[k] = input[k];
  }
  return out;
}

function shapeOf(o) {
  return Object.keys(o).join('>');
}

