function buildEvent(type, payload, opts) {
  const e = {};
  e.type = type;
  e.ts = Date.now();
  if (opts.userId) e.userId = opts.userId;     // sometimes present
  if (opts.sessionId) e.sessionId = opts.sessionId;
  // copy arbitrary payload fields onto the event
  for (const k in payload) e[k] = payload[k];
  e.weight = opts.weight ? opts.weight : 1;    // 1 (Smi) or a float
  return e;
}
